    def test_sortie_partial_active_label_ids_track_dominance(self):
        old = _SortiePartialLabel(
            sequence=(1,),
            mask=1,
            last=1,
            partial=_PartialNoWaitingPathProfile(
                arc_options=tuple(),
                lower_start=0.0,
                upper_start=20.0,
                offset=0.0,
                travel_cost=5.0,
                travel_energy=5.0,
                service_cost=0.0,
                service_energy=0.0,
            ),
        )
        better = _SortiePartialLabel(
            sequence=(1,),
            mask=1,
            last=1,
            partial=_PartialNoWaitingPathProfile(
                arc_options=tuple(),
                lower_start=0.0,
                upper_start=20.0,
                offset=0.0,
                travel_cost=4.0,
                travel_energy=5.0,
                service_cost=0.0,
                service_energy=0.0,
            ),
        )
        worse = _SortiePartialLabel(
            sequence=(1,),
            mask=1,
            last=1,
            partial=_PartialNoWaitingPathProfile(
                arc_options=tuple(),
                lower_start=0.0,
                upper_start=20.0,
                offset=0.0,
                travel_cost=6.0,
                travel_energy=5.0,
                service_cost=0.0,
                service_energy=0.0,
            ),
        )
        labels = [old]
        active_ids = {id(old)}

        self.assertTrue(_add_sortie_partial_label(labels, better, active_label_ids=active_ids))
        self.assertEqual(labels, [better])
        self.assertNotIn(id(old), active_ids)
        self.assertIn(id(better), active_ids)

        self.assertFalse(_add_sortie_partial_label(labels, worse, active_label_ids=active_ids))
        self.assertEqual(labels, [better])
        self.assertNotIn(id(worse), active_ids)

    def test_sortie_partial_dominance_index_matches_list_scan(self):
        def label(
            sequence: tuple[int, ...],
            lower_start: float,
            upper_start: float,
            offset: float,
            travel_cost: float,
            travel_energy: float,
        ) -> _SortiePartialLabel:
            mask = 0
            for task in sequence:
                mask |= 1 << int(task)
            return _SortiePartialLabel(
                sequence=sequence,
                mask=mask,
                last=sequence[-1],
                partial=_PartialNoWaitingPathProfile(
                    arc_options=tuple(),
                    lower_start=lower_start,
                    upper_start=upper_start,
                    offset=offset,
                    travel_cost=travel_cost,
                    travel_energy=travel_energy,
                    service_cost=0.0,
                    service_energy=0.0,
                ),
            )

        base = [
            label((1, 2), 0.0, 100.0, 10.0, 10.0, 5.0),
            label((2, 1), 5.0, 90.0, 12.0, 12.0, 5.0),
            label((3, 1), 0.0, 80.0, 30.0, 6.0, 8.0),
        ]
        candidates = [
            label((4, 1), 6.0, 80.0, 14.0, 14.0, 5.0),
            label((5, 1), 0.0, 110.0, 8.0, 8.0, 4.0),
            label((6, 1), 50.0, 60.0, 50.0, 50.0, 50.0),
        ]
        for candidate in candidates:
            list_scan = list(base)
            indexed = list(base)
            active_list = {id(item) for item in list_scan}
            active_indexed = {id(item) for item in indexed}
            dominance_index = _SortiePartialDominanceIndex(indexed)

            list_result = _add_sortie_partial_label(
                list_scan,
                candidate,
                active_label_ids=active_list,
            )
            indexed_result = _add_sortie_partial_label(
                indexed,
                candidate,
                active_label_ids=active_indexed,
                dominance_index=dominance_index,
            )

            self.assertEqual(indexed_result, list_result)
            self.assertEqual([item.sequence for item in indexed], [item.sequence for item in list_scan])
            self.assertEqual(active_indexed, active_list)

