    def _run_sharded_dummy_driver_smoke(
        self,
        dummy_statuses: str,
        *,
        enabled: bool,
        dummy_engine_enabled: bool | None = None,
        allow_test_dummy_certificate: bool = True,
        allow_dummy_env: bool = True,
        toy_certificate_enabled: bool = False,
        archive_enabled: bool = False,
        bound_enabled: bool = False,
        support_harvest_enabled: bool = False,
        negative_harvest_limit: int = 0,
        pulse_audit_enabled: bool = False,
        pulse_audit_dummy_statuses: str = "",
        pulse_audit_time_limit: float = 0.2,
        hidden_worker_enabled: bool = False,
        hidden_worker_dummy_statuses: str = "",
        hidden_worker_time_limit: float = 0.2,
        hidden_worker_max_recursions: int = 100000,
        hidden_worker_harvest_enabled: bool = True,
        hidden_worker_harvest_limit: int = 4,
        task_waiting_allowed: bool | None = None,
    ) -> tuple[Any, list[dict[str, Any]], list[dict[str, Any]]]:
        data = load_future_data("very_small")
        if task_waiting_allowed is not None:
            data = _with_task_waiting_allowed(data, bool(task_waiting_allowed))
        if dummy_engine_enabled is None:
            dummy_engine_enabled = bool(enabled)
        with tempfile.TemporaryDirectory() as tmp:
            log_path = Path(tmp) / "sharded_dummy_driver_smoke.jsonl"
            config = {
                "time_limit": 5.0,
                "journey_max_cg_iterations": 2,
                "journey_initial_pool_integer_enabled": False,
                "journey_pool_integer_heuristic_enabled": False,
                "journey_pool_time_limit": 1.0,
                "initial_single_task_starts_per_task": 3,
                "journey_initial_source_trip_limit": 500,
                "journey_initial_max_columns": 100,
                "journey_pool_max_columns": 100,
                "journey_pool_max_extensions_per_prefix": 80,
                "journey_pricing_time_limit": 0.2,
                "journey_min_pricing_time": 0.0,
                "journey_post_pricing_time_reserve": 0.0,
                "journey_certificate_no_reserve_enabled": True,
                "journey_certificate_no_reserve_min_cg_iter": 1,
                "journey_final_judge_sharding_enabled": bool(enabled),
                "journey_sharded_pulse_dummy_engine_enabled": bool(dummy_engine_enabled),
                "journey_sharded_pulse_allow_test_dummy_certificate": bool(
                    allow_test_dummy_certificate
                ),
                "journey_pulse_toy_certificate_enabled": bool(toy_certificate_enabled),
                "journey_pulse_archive_enabled": bool(archive_enabled),
                "journey_pulse_bound_pruning_enabled": bool(bound_enabled),
                "journey_pulse_support_aware_harvesting_enabled": bool(support_harvest_enabled),
                "journey_pulse_negative_harvest_limit": int(negative_harvest_limit),
                "journey_final_judge_dummy_shard_statuses": str(dummy_statuses),
                "journey_sharded_pulse_audit_enabled": bool(pulse_audit_enabled),
                "journey_sharded_pulse_audit_after_legacy_final_judge": True,
                "journey_sharded_pulse_audit_time_limit": float(pulse_audit_time_limit),
                "journey_sharded_pulse_audit_max_recursions": 100000,
                "journey_sharded_pulse_audit_log_disagreements": True,
                "journey_sharded_pulse_audit_allow_certificate_effect": False,
                "journey_sharded_pulse_audit_dummy_engine_enabled": bool(
                    pulse_audit_dummy_statuses
                ),
                "journey_sharded_pulse_audit_allow_test_dummy_certificate": True,
                "journey_sharded_pulse_audit_dummy_statuses": str(pulse_audit_dummy_statuses),
                "journey_sharded_pulse_hidden_negative_worker_enabled": bool(
                    hidden_worker_enabled
                ),
                "journey_sharded_pulse_hidden_negative_worker_trigger": "before_legacy_final_judge",
                "journey_sharded_pulse_hidden_negative_worker_time_limit": float(
                    hidden_worker_time_limit
                ),
                "journey_sharded_pulse_hidden_negative_worker_max_recursions": int(
                    hidden_worker_max_recursions
                ),
                "journey_sharded_pulse_hidden_negative_worker_archive_enabled": True,
                "journey_sharded_pulse_hidden_negative_worker_bound_pruning_enabled": True,
                "journey_sharded_pulse_hidden_negative_worker_harvesting_enabled": bool(
                    hidden_worker_harvest_enabled
                ),
                "journey_sharded_pulse_hidden_negative_worker_negative_harvest_limit": int(
                    hidden_worker_harvest_limit
                ),
                "journey_sharded_pulse_hidden_negative_worker_max_columns": 4,
                "journey_sharded_pulse_hidden_negative_worker_dummy_engine_enabled": bool(
                    hidden_worker_dummy_statuses
                ),
                "journey_sharded_pulse_hidden_negative_worker_allow_test_dummy_certificate": True,
                "journey_sharded_pulse_hidden_negative_worker_dummy_statuses": str(
                    hidden_worker_dummy_statuses
                ),
                "journey_pricing_profile_pricing_enabled": False,
                "journey_pricing_direct_journey_label_pricing_enabled": False,
                "journey_pricing_max_sequences": 1,
                "journey_pricing_max_timed_evaluations": 1,
                "journey_pricing_max_candidate_trips": 1,
                "journey_pricing_max_dp_states": 1,
                "journey_static_fleet_lb_cut_enabled": False,
            }
            logger = FutureLogger(log_path, console=False)
            try:
                env_value = "1" if bool(allow_dummy_env) else ""
                with patch.dict("os.environ", {"BPC_FUTURE_ALLOW_DUMMY_CERTIFICATE": env_value}):
                    result = solve_bpc_future_journey(data, config, logger=logger)
            finally:
                logger.close()
            records = [json.loads(line) for line in log_path.read_text(encoding="utf-8").splitlines()]
        sharded_pricing = [
            record
            for record in records
            if record.get("event") == "journey_pricing"
            and record.get("final_judge_engine") in {"sharded_pulse", "sharded_pulse_dummy"}
        ]
        return result, records, sharded_pricing

    def _pulse_audit_pricing_result(
        self,
        state: str,
        *,
        reason: str = "",
        best_rc: float | None = None,
    ) -> JourneyPricingResult:
        if state == PRICING_STATE_CERTIFIED_NO_NEGATIVE:
            if not reason:
                reason = "sharded_pulse_no_negative_journey"
            return JourneyPricingResult(
                [],
                True,
                0.0 if best_rc is None else float(best_rc),
                0,
                0,
                0,
                0,
                "OPTIMAL",
                reason,
                global_certificate_capable=True,
                final_judge_engine="sharded_pulse"
                if reason == "sharded_pulse_no_negative_journey"
                else "",
                final_judge_certificate_capable=reason == "sharded_pulse_no_negative_journey",
                completion_bound_enabled=reason == "direct_label_no_negative_journey",
                pricing_state=PRICING_STATE_CERTIFIED_NO_NEGATIVE,
                final_judge_shards_total=1,
                final_judge_shards_certified=1,
            )
        if state == PRICING_STATE_FOUND_NEGATIVE:
            return JourneyPricingResult(
                [],
                False,
                -1.0 if best_rc is None else float(best_rc),
                0,
                0,
                0,
                0,
                "FOUND_NEGATIVE",
                reason or "negative_journey_found",
                pricing_state=PRICING_STATE_FOUND_NEGATIVE,
                final_judge_shards_total=1,
                final_judge_shards_negative_found=1,
            )
        return JourneyPricingResult(
            [],
            False,
            best_rc,
            0,
            0,
            0,
            0,
            "INCOMPLETE",
            reason or "time_limit",
            pricing_state=PRICING_STATE_INCOMPLETE_LIMIT,
            final_judge_shards_total=1,
            final_judge_shards_incomplete=1,
        )

    def test_sharded_pulse_audit_payload_agreement_and_disagreements(self):
        legacy_certified = self._pulse_audit_pricing_result(
            PRICING_STATE_CERTIFIED_NO_NEGATIVE,
            reason="direct_label_no_negative_journey",
        )
        pulse_certified = self._pulse_audit_pricing_result(PRICING_STATE_CERTIFIED_NO_NEGATIVE)
        payload = _journey_sharded_pulse_audit_payload(
            legacy_certified,
            pulse_certified,
            elapsed=0.01,
        )
        self.assertTrue(payload["pulse_audit_agrees_with_legacy"])
        self.assertEqual(payload["pulse_audit_disagreement_type"], "")
        self.assertEqual(payload["pulse_audit_comparison_type"], "legacy_certified_pulse_certified")
        self.assertEqual(payload["pulse_audit_disagreement_severity"], "info")
        self.assertTrue(payload["pulse_audit_global_certificate_capable"])
        self.assertEqual(payload["pulse_audit_status"], PRICING_STATE_CERTIFIED_NO_NEGATIVE)

        pulse_negative = self._pulse_audit_pricing_result(PRICING_STATE_FOUND_NEGATIVE)
        self.assertEqual(
            _journey_sharded_pulse_audit_disagreement_type(legacy_certified, pulse_negative),
            "legacy_certified_pulse_negative",
        )
        negative_payload = _journey_sharded_pulse_audit_payload(
            legacy_certified,
            pulse_negative,
            elapsed=0.01,
        )
        self.assertEqual(negative_payload["pulse_audit_disagreement_severity"], "critical")
        legacy_negative = self._pulse_audit_pricing_result(PRICING_STATE_FOUND_NEGATIVE)
        self.assertEqual(
            _journey_sharded_pulse_audit_disagreement_type(legacy_negative, pulse_certified),
            "legacy_negative_pulse_certified",
        )
        legacy_incomplete = self._pulse_audit_pricing_result(PRICING_STATE_INCOMPLETE_LIMIT)
        self.assertEqual(
            _journey_sharded_pulse_audit_disagreement_type(legacy_incomplete, pulse_certified),
            "legacy_incomplete_pulse_certified",
        )
        for legacy_state, pulse_state, expected in (
            (
                PRICING_STATE_CERTIFIED_NO_NEGATIVE,
                PRICING_STATE_INCOMPLETE_LIMIT,
                "legacy_certified_pulse_incomplete",
            ),
            (
                PRICING_STATE_FOUND_NEGATIVE,
                PRICING_STATE_FOUND_NEGATIVE,
                "legacy_negative_pulse_negative",
            ),
            (
                PRICING_STATE_FOUND_NEGATIVE,
                PRICING_STATE_INCOMPLETE_LIMIT,
                "legacy_negative_pulse_incomplete",
            ),
            (
                PRICING_STATE_INCOMPLETE_LIMIT,
                PRICING_STATE_FOUND_NEGATIVE,
                "legacy_incomplete_pulse_negative",
            ),
            (
                PRICING_STATE_INCOMPLETE_LIMIT,
                PRICING_STATE_INCOMPLETE_LIMIT,
                "legacy_incomplete_pulse_incomplete",
            ),
        ):
            payload = _journey_sharded_pulse_audit_payload(
                self._pulse_audit_pricing_result(legacy_state),
                self._pulse_audit_pricing_result(pulse_state),
                elapsed=0.01,
            )
            self.assertEqual(payload["pulse_audit_comparison_type"], expected)
            self.assertEqual(
                payload["pulse_audit_disagreement_type"],
                "" if legacy_state == pulse_state else expected,
            )

    def test_sharded_pulse_audit_certified_log_does_not_change_official_bound(self):
        result, records, sharded_pricing = self._run_sharded_dummy_driver_smoke(
            "CERTIFIED_NO_NEGATIVE",
            enabled=False,
            pulse_audit_enabled=True,
            pulse_audit_dummy_statuses="CERTIFIED_NO_NEGATIVE",
        )
        self.assertIsNone(result.dual_bound)
        self.assertEqual(sharded_pricing, [])
        audits = [record for record in records if record.get("event") == "journey_sharded_pulse_audit"]
        self.assertTrue(audits)
        audit = audits[-1]
        self.assertTrue(audit["pulse_audit_enabled"])
        self.assertFalse(audit["pulse_audit_allow_certificate_effect"])
        self.assertEqual(audit["pulse_audit_status"], PRICING_STATE_CERTIFIED_NO_NEGATIVE)
        self.assertEqual(audit["pulse_audit_disagreement_type"], "legacy_incomplete_pulse_certified")
        self.assertEqual(audit["pulse_audit_disagreement_severity"], "warning")
        self.assertEqual(audit["pulse_audit_comparison_type"], "legacy_incomplete_pulse_certified")
        self.assertTrue(audit["pulse_audit_global_certificate_capable"])
        self.assertEqual(audit["pulse_audit_shards_certified"], 1)
        for key in (
            "pulse_audit_context_hash",
            "pulse_audit_true_dual_hash",
            "pulse_audit_cut_hash",
            "pulse_audit_branch_hash",
            "pulse_audit_forbidden_signature_hash",
        ):
            self.assertIn(key, audit)
            self.assertIsInstance(audit[key], str)
            self.assertTrue(audit[key])
        self.assertTrue(
            all(
                not (
                    record.get("event") == "journey_pricing"
                    and record.get("pricing_state") == PRICING_STATE_CERTIFIED_NO_NEGATIVE
                )
                for record in records
            )
        )

