def _option(path_type: str, time_min: float, energy: float, risk: float, distance: float) -> dict[str, object]:
    return {
        "path_type": path_type,
        "aliases": [path_type],
        "travel_time_min": time_min,
        "energy_proxy": energy,
        "risk_integral": risk,
        "path_distance_km": distance,
        "path_cells": [[0, 0], [1, 1]],
        "path_xy": [[10.0, 10.0], [12.0, 10.0]],
    }


